WITH RecentRevisionCounts AS (
    SELECT
        ph.PostId,
        ph.UserId,
        COUNT(*) AS RecentPeHistoryCount
    FROM 
        PostHistory ph
    WHERE
        ph.CreationDate > current_date - interval '30 day'
        AND ph.PostHistoryTypeId IN (4, 5, 6) -- Edit Title, Edit Body, Edit Tags
    GROUP BY
        ph.PostId, ph.UserId
),
TopUsersQuestions AS (
    SELECT
        u.Id AS UserId,
        u.DisplayName,
        EOQ.QPostsInLast60Days,
        COALESCE(EOQ.FullDataTrendingEdits, 0) AS TrendingEditScore
    FROM
        Users u
        LEFT JOIN LATERAL (
            SELECT COUNT(*) AS QPostsInLast60Days
            FROM Posts p
            WHERE p.OwnerUserId = u.Id -- authored posts
              AND p.PostTypeId = 1    -- question type
